import {salaryItems,SALARY_VERSION} from '../../assets/native-salary-catalog-model.js';
import {salaryFingerprint} from '../../lib/internal-native-salary.js';
export const uid=n=>`10000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
export const row=(patch={})=>({kind:'concept',code:'95',agreementCode:'1',categoryCode:null,label:'Concepto sintético sin regla municipal',nature:'remuneration',unit:'units',precision:2,value:null,validFrom:'2026-10',validUntil:null,ruleReference:'Documento sintético QA, no homologado',dependencies:[],active:true,...patch});
export const body=(patch={})=>({command:'propose',scopeVersion:'a'.repeat(64),baseVersion:'b'.repeat(64),classificationVersion:'c'.repeat(64),proposalId:null,proposalSha256:null,items:salaryItems([row()]),reason:'Revisión sintética de definición sin cálculo',reviewConfirmed:false,...patch});
export function proposal(items=[row()],patch={}){const b=body({items:salaryItems(items)});return {id:uid(10),status:'pending',requestSha256:salaryFingerprint(b),baseVersion:b.baseVersion,classificationVersion:b.classificationVersion,reason:b.reason,baseItems:[],items:b.items,createdAt:'2026-10-02T12:00:00Z',authorLabel:'Preparador sintético QA',canReview:true,decision:null,...patch};}
export const bootstrap=(patch={})=>({version:SALARY_VERSION,scopeVersion:'a'.repeat(64),classification:{version:'c'.repeat(64),items:[{kind:'agreements',code:'1',label:'Convenio sintético'},{kind:'categories',code:'6',agreementCode:'1',label:'Clase sintética'}]},catalog:{version:'b'.repeat(64),revision:0,items:[]},proposals:[],complete:true,permissions:{canPropose:true,canReview:true},payrollCalculated:false,payrollPosted:false,...patch});
export function receipt(input=body(),patch={}){return {version:SALARY_VERSION,eventId:uid(11),proposalId:input.command==='propose'?uid(11):input.proposalId,requestKey:uid(9),requestSha256:salaryFingerprint(input),body:input,status:({propose:'pending',approve:'approved',reject:'rejected'})[input.command],revision:input.command==='approve'?1:0,catalogVersion:'b'.repeat(64),replayed:false,payrollCalculated:false,payrollPosted:false,...patch};}
